import 'package:better_auth_flutter/better_auth_flutter.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await BetterAuthFlutter.initialize(url: 'https://example.com/api/auth');
  runApp(const MyApp());
}

Future<void> signIn() async {
  final result = await BetterAuthFlutter.client.signInEmail(email: 'user@example.com', password: 'secret');
  result.when(
    success: (data) => print('Welcome ${data.user?.name}'),
    failure: (error) => print('Error: ${error.message}'),
  );
}
